WITH ndsd AS (SELECT sc.SEC_SNAME AS `名称`, idx.F110101 AS `利润` FROM VIEW_STK_FIN_IDX idx JOIN GET_A_SEC_CODE sc ON idx.COMCODE = sc.COMCODE AND sc.ISVALID = 1 WHERE sc.SEC_SNAME LIKE '%宁德时代%' AND idx.ISVALID = 1 AND idx.F110101 IS NOT NULL AND YEAR(idx.ENDDATE) = 2025 AND MONTH(idx.ENDDATE) = 12 AND DAY(idx.ENDDATE) = 31 ORDER BY idx.ENDDATE DESC LIMIT 1), zsyh AS (SELECT sc.SEC_SNAME AS `名称`, idx.F110101 AS `利润` FROM VIEW_STK_FIN_IDX idx JOIN GET_A_SEC_CODE sc ON idx.COMCODE = sc.COMCODE AND sc.ISVALID = 1 WHERE sc.SEC_SNAME LIKE '%招商银行%' AND idx.ISVALID = 1 AND idx.F110101 IS NOT NULL AND YEAR(idx.ENDDATE) = 2025 AND MONTH(idx.ENDDATE) = 12 AND DAY(idx.ENDDATE) = 31 ORDER BY idx.ENDDATE DESC LIMIT 1) SELECT n.`名称` AS `公司1名称`, ROUND(n.`利润` / 10000, 1) AS `公司1归母净利润(万)`, z.`名称` AS `公司2名称`, ROUND(z.`利润` / 10000, 1) AS `公司2归母净利润(万)`, CASE WHEN n.`利润` > z.`利润` THEN n.`名称` WHEN n.`利润` < z.`利润` THEN z.`名称` ELSE '利润相同' END AS `利润更高者`, ROUND(ABS(n.`利润` - z.`利润`) / 10000, 1) AS `高出金额(万)` FROM ndsd n CROSS JOIN zsyh z;
